body:
The following minimal example will result in a crash on font.**loadFromFile**() call. Link to a forum post about this issue is [here](http://en.sfml-dev.org/forums/index.php?topic=19753.msg142173#msg142173). I am using Android SDK 6.0 (api 23).

``` c++
#include <SFML/Window.hpp>
#include <SFML/Graphics.hpp>
#include <iostream>

int main()
{
    sf::Window window(sf::VideoMode(800, 600), "My window");

    sf::Font font;

    if(!font.loadFromFile("assets/sansation.ttf")) // <-- CRASH
    {
        std::cerr << "Could not load font" << std::endl;
        return 1;
    }

    // run the program as long as the window is open
    while (window.isOpen())
    {
        // check all the window's events that were triggered since the last iteration of the loop
        sf::Event event;
        while (window.pollEvent(event))
        {
            // "close requested" event: we close the window
            if (event.type == sf::Event::Closed)
                window.close();
        }
    }

    return 0;
}
```

